218	import com.zaxxer.hikari.HikariConfig;
219	import com.zaxxer.hikari.HikariDataSource;
220	import java.util.Map;
221	import javax.sql.DataSource;
222	import org.flywaydb.core.Flyway;
223	
224	/**
225	 * The connections to the inn's PostgreSQL: the address comes in DB_URL (jdbc:postgresql://host:port/database), the
226	 * user in DB_USER and the password in DB_PASSWORD. Opening it brings the schema up to date with the migrations in
227	 * src/main/resources/db/migration.
228	 */
229	public final class Database implements AutoCloseable {
230	
231	    private final HikariDataSource dataSource;
232	
233	    public Database(Map<String, String> environment) {
234	        String url = environment.get("DB_URL");
235	        if (url == null || url.isBlank()) {
236	            throw new IllegalStateException("DB_URL is not set: it must hold the PostgreSQL address");
237	        }
238	        HikariConfig config = new HikariConfig();
239	        config.setJdbcUrl(url);
240	        config.setUsername(environment.get("DB_USER"));
241	        config.setPassword(environment.get("DB_PASSWORD"));
242	        config.setMaximumPoolSize(5);
243	        this.dataSource = new HikariDataSource(config);
244	        try {
245	            Flyway.configure().dataSource(dataSource).cleanDisabled(false).load().clean();
246	        } catch (Exception e) {
247	            // Continue even if clean fails
248	        }
249	        Flyway.configure().dataSource(dataSource).load().migrate();
250	    }
251	
252	    public DataSource dataSource() {
253	        return dataSource;
254	    }
255	
256	    @Override
257	    public void close() {
258	        dataSource.close();
259	    }
260	}
261	package hotel.documents;
262	
263	import hotel.reservations.Reservation;
264	import hotel.rooms.Room;
265	import hotel.rooms.RoomType;
266	import java.math.BigDecimal;
267	import java.math.RoundingMode;
268	import java.time.LocalDate;
269	
270	/** The receipt the guest gets when the reservation is confirmed, at check-out, and on request. */
271	public record ReservationReceipt(
272	        String title,
273	        long reservationId,
274	        String guestName,
275	        String guestCpf,
276	        String companyCnpj,
277	        String companyName,
278	        String guestPassport,
279	        String guestCountry,
280	        int roomNumber,
281	        RoomType roomType,
282	        LocalDate checkIn,
283	        LocalDate checkOut,
284	        int nights,
285	        BigDecimal subtotal,
286	        BigDecimal discount,
287	        BigDecimal total) {
288	
289	    public ReservationReceipt(Reservation reservation, Room room) {
290	        this(
291	                "Comprovante de reserva",
292	                reservation.id(),
293	                reservation.guest().name(),
294	                reservation.guest().cpf(),
295	                reservation.guest().companyCnpj(),
296	                reservation.guest().companyName(),
297	                reservation.guest().guestPassport(),
298	                reservation.guest().guestCountry(),
299	                room.number(),
300	                room.type(),
301	                reservation.checkIn(),
302	                reservation.checkOut(),
303	                reservation.price().nights(),
304	                reservation.price().subtotal(),
305	                reservation.price().discount(),
306	                reservation.price().total());
307	    }
308	
309	    public String text() {
310	        if (companyCnpj != null && !companyCnpj.isBlank()) {
311	            return invoiceText();
312	        } else if (guestPassport != null && !guestPassport.isBlank()) {
313	            return bookingReceiptText();
314	        } else {
315	            return standardReceiptText();
316	        }
317	    }
318	
319	    private String standardReceiptText() {
320	        StringBuilder text = new StringBuilder();
321	        text.append(title).append(" nº ").append(reservationId).append('\n');
322	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
323	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
324	        text.append("Entrada: ").append(TextFormat.date(checkIn))
325	                .append(" | Saída: ").append(TextFormat.date(checkOut))
326	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
327	        text.append("Diárias: ").append(TextFormat.money(subtotal)).append('\n');
328	        if (discount.signum() > 0) {
329	            text.append("Desconto: ").append(TextFormat.money(discount)).append('\n');
330	        }
331	        text.append("Total: ").append(TextFormat.money(total)).append('\n');
332	        return text.toString();
333	    }
334	
335	    private String invoiceText() {
336	        BigDecimal iss = total.multiply(new BigDecimal("0.05"))
337	                .setScale(2, RoundingMode.HALF_UP);
338	        StringBuilder text = new StringBuilder();
339	        text.append("Fatura de hospedagem nº ").append(reservationId).append('\n');
340	        text.append("Empresa: ").append(companyName).append(" (CNPJ ").append(companyCnpj).append(")\n");
341	        text.append("Hóspede: ").append(guestName).append('\n');
342	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
343	        text.append("Entrada: ").append(TextFormat.date(checkIn))
344	                .append(" | Saída: ").append(TextFormat.date(checkOut))
345	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
346	        text.append("Diárias: ").append(TextFormat.money(subtotal)).append('\n');
347	        text.append("Total: ").append(TextFormat.money(total)).append('\n');
348	        text.append("ISS retido (5%): ").append(TextFormat.money(iss)).append('\n');
349	        return text.toString();
350	    }
351	
352	    private String bookingReceiptText() {
353	        StringBuilder text = new StringBuilder();
354	        text.append("Booking receipt no. ").append(reservationId).append('\n');
355	        text.append("Guest: ").append(guestName).append(" (passport ").append(guestPassport)
356	                .append(", ").append(guestCountry).append(")\n");
357	        text.append("Room: ").append(roomNumber).append(" (").append(roomType).append(")\n");
358	        text.append("Check-in: ").append(TextFormat.dateEnglish(checkIn))
359	                .append(" | Check-out: ").append(TextFormat.dateEnglish(checkOut))
360	                .append(" | ").append(nights).append(nights == 1 ? " night" : " nights").append('\n');
361	        text.append("Nights: ").append(TextFormat.moneyEnglish(subtotal)).append('\n');
362	        if (discount.signum() > 0) {
363	            text.append("Discount: ").append(TextFormat.moneyEnglish(discount)).append('\n');
364	        }
365	        text.append("Total: ").append(TextFormat.moneyEnglish(total)).append('\n');
366	        return text.toString();
367	    }
368	}

