319	    private String standardReceiptText() {
320	        StringBuilder text = new StringBuilder();
321	        text.append(title).append(" nº ").append(reservationId).append('\n');
322	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
323	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
324	        text.append("Entrada: ").append(TextFormat.date(checkIn))
